```latex
\documentclass{article}
\usepackage{pgfplots}
\usepgfplotslibrary{pie}
\usepackage{tikz}

\begin{document}

\begin{figure}[h]
\centering
\begin{tikzpicture}
\begin{axis}[
    pie,
    text=legend,
    radius=3,
    scale font,
    legend style={at={(1.2,0.5)}, anchor=west},
    title={2023年公司各部门预算分配},
    title style={yshift=10pt}
]

\pie[
    text=inside,
    color={blue!30, red!30, green!30, yellow!30, orange!30}
]{
    35/研发部门,
    25/市场部门,
    20/行政部门,
    12/人力资源,
    8/其他
}

\end{axis}
\end{tikzpicture}
\caption{公司各部门预算分配饼图}
\end{figure}

\end{document}
```

